import unittest,re
from tools.kjv_archive import load_register,read
class HaggaiUnequalContactTests(unittest.TestCase):
 def test_presence_and_unequal_contact(self):
  prior,_=load_register('0.10-kjv.182');lang,manifest=load_register('0.10-kjv.183')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('haggai-'):c for c in read(lang.folder/'haggai-presence-and-unequal-contact-cases.json')};self.assertEqual(len(cases),38)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship','care'}&set(r['keys']))
  anchors={'1:1': ['two:ord year of kjv_darius', 'six:ord month', 'one_num:ord day', 'kjv_zerubbabel_shealtiel son of kjv_shealtiel', 'kjv_joshua_josedech son of kjv_josedech_haggai'], '1:2': ['this people say:pr', 'time come:neg:perf', 'time that house of kjv_lord build:psv:should'], '1:3': ['then word of kjv_lord', 'by kjv_haggai_prophet prophet'], '1:4': ['your/house:pl with kjv_ceiling cover:psv:adj', 'this house kjv_desolate lie'], '1:5': ['your/way:pl consider:imp'], '1:6': ['much kjv_sow:perf', 'little in bring', 'enough have:neg', 'fill:psv:neg', 'none warm', 'kjv_wages gain:pr kjv_wages gain:pr', 'bag with hole:pl'], '1:7': ['your/way:pl consider:imp'], '1:8': ['wood bring', 'house build', 'ipl in it pleasure take', 'ipl glorify:psv'], '1:9': ['for much look', 'to little come', 'ipl upon it blow', 'why:q', 'mypl/house', 'every man to his/own house'], '1:10': ['heaven over you from dew stay:psv', 'earth from her/fruit stay:psv'], '1:11': ['ipl for kjv_drought', 'upon corn', 'upon new wine', 'upon oil', 'upon kjv_livestock', 'all labour of hand:pl'], '1:12': ['kjv_joshua_josedech son of kjv_josedech_haggai', 'voice of kjv_lord their/god', 'word:pl of kjv_haggai_prophet', 'people before kjv_lord fear'], '1:13': ['messenger of kjv_lord', 'kjv_message of kjv_lord', 'ipl with you be:pr kjv_lord say'], '1:14': ['spirit of kjv_zerubbabel_shealtiel', 'spirit of kjv_joshua_josedech', 'spirit of all remainder', 'they come', 'their/god work'], '1:15': ['two+twelve:ord day', 'six:ord month', 'two:ord year'], '2:1': ['seven:ord month', 'twelve and nine:ord day'], '2:2': ['kjv_zerubbabel_shealtiel son of kjv_shealtiel', 'kjv_joshua_josedech son of kjv_josedech_haggai', 'remainder of people'], '2:3': ['her/one_num:ord glory', 'how you it now see', 'compare:ev of it as nothing be:neg:q'], '2:4': ['strong be:imp oh kjv_zerubbabel_shealtiel', 'strong be:imp oh kjv_joshua_josedech', 'strong be:imp all you people', 'ipl with you'], '2:5': ['ipl with you kjv_covenant make', 'out of egypt', 'mypl/spirit among you remain', 'fear:neg:imp'], '2:6': ['yet once', 'little while', 'ipl heaven:pl and earth and sea and dry land shake'], '2:7': ['ipl all nation:pl shake', 'desire of all nation:pl come', 'ipl this house with glory fill'], '2:8': ['silver of ipl', 'gold of ipl'], '2:9': ['this later house greater than of former', 'in this place ipl peace give'], '2:10': ['two+twelve:ord day', 'nine:ord month', 'two:ord year'], '2:11': ['priest:pl about law ask'], '2:12': ['holy flesh', 'his/clothing carry', 'his/kjv_skirt_garment', 'bread or kjv_pottage or wine or oil or any food', 'it holy be:fu:q', 'say:pa no'], '2:13': ['by kjv_corpse kjv_unclean_ritual', 'any of these touch', 'it kjv_unclean_ritual be:fu:q', 'say:pa it kjv_unclean_ritual be:fu'], '2:14': ['this nation before ipl', 'every work of their/hand:pl', 'they there offer', 'kjv_unclean_ritual be:pr'], '2:15': ['ipl you:a ask:pr', 'from this day and up', 'stone upon stone', 'lay:psv'], '2:16': ['person to kjv_heap of twelve and eight measure:pl', 'but ten', 'person to kjv_wine_vat', 'four+twelve and two vessel:pl', 'out of kjv_winepress', 'but twelve and eight'], '2:17': ['kjv_blasting', 'kjv_mildew', 'hail', 'your/hand:pl', 'to ipl turn:neg'], '2:18': ['two+twelve:ord day of nine:ord month', 'kjv_foundation of kjv_temple', 'it consider:imp'], '2:19': ['seed yet in kjv_barn be:q', 'kjv_vine and fig kjv_tree and pomegranate and kjv_olive kjv_tree', 'forth bring:neg:perf', 'from this day ipl you:a bless:fu'], '2:20': ['again word of kjv_lord', 'two+twelve:ord day of month'], '2:21': ['kjv_governor of kjv_judah', 'ipl heaven:pl and earth shake'], '2:22': ['ipl throne of kingdom:pl', 'strength of kingdom:pl of kjv_heathen', 'chariot:pl', 'horse:pl and their/ride:ag:pl', 'every person by sword of his/brother'], '2:23': ['mypl/servant son of kjv_shealtiel', 'as kjv_signet make', 'ipl thou:a choose:perf']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('ipl glorify:psv:fu',cases['1-8']['analysis'])
  self.assertIn('mypl/spirit among you remain:pr',cases['2-5']['analysis'])
  self.assertIn('say:pa no',cases['2-12']['analysis'])
  self.assertIn('say:pa it kjv_unclean_ritual be:fu',cases['2-13']['analysis'])
  self.assertIn('forth bring:neg:perf',cases['2-19']['analysis'])
  self.assertFalse(any(':du' in c['analysis'] or 'wesg' in c['analysis'] for c in cases.values()))
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),2)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
